Translate("zhCN", "magatha-grimtotem", {
	title = "玛加萨·恐怖图腾",
	subtitle = "恐怖图腾的老祖母",
	found = "她在长者高地上的小屋",
	hint = "向住在长者高地上的老祖母求教。",
	allegiance = "恐怖图腾氏族 · 雷霆崖",
	aliases = { "玛加萨", "老祖母" },
	sections = {
		{
			title = "概述",
			text = [=[玛加萨·恐怖图腾是{link:grimtotem-clan}恐怖图腾{/link}的老祖母，许多人认为她是{link:tauren}牛头人{/link}中最强大的萨满祭司，也是牛头人最年长的长老之一。她住在{link:elder-rise}长者高地{/link}上的一座小屋里，由她氏族的两名战士和她的仆人拉哈罗侍奉。许多人前来向她求教，她也乐于给出建议。至于她想要什么作为回报，很少有人说得清。]=],
		},
		{
			title = "意义",
			text = [=[玛加萨是{link:cairne-bloodhoof}凯恩·血蹄{/link}的头号对手。她几乎一生都在追求权力与地位，并相信只有她才配领导{link:tauren}牛头人{/link}。她氏族的战士追随她，梦想着把低等种族赶出{link:kalimdor}卡利姆多{/link}。然而她却住在大酋长的城市里，坐在他的长老之中，并为{link:forsaken}被遗忘者{/link}说话，她对他们的帮助超过了任何其他牛头人。]=],
		},
		{
			title = "事迹",
			text = [=[• 她还是个女孩时，便被赐予了萨满祭司的天赋。
