Translate("zhCN", "grimtotem-clan", {
	title = "恐怖图腾氏族",
	aliases = { "恐怖图腾部族", "恐怖图腾" },
	sections = {
		{
			title = "概述",
			text = [=[恐怖图腾是一个与众不同的{link:tauren}牛头人{/link}氏族。大多数牛头人寻求与大地和谐共处，恐怖图腾却寻求主宰大地。他们相信应当把低等种族赶出{link:kalimdor}卡利姆多{/link}，牛头人应当夺回祖先的土地。他们的女族长是{link:magatha-grimtotem}老祖母{/link}玛加萨，他们的战士追随着她。]=],
		},
		{
			title = "氏族与城市",
			text = [=[{link:magatha-grimtotem}玛加萨{/link}住在{link:thunder-bluff}雷霆崖{/link}的{link:elder-rise}长者高地{/link}上，由她氏族的战士守卫，那里的恐怖图腾享有任何{link:tauren}牛头人{/link}都享有的权利。据说{link:cairne-bloodhoof}凯恩{/link}让她住得离自己如此之近，是出于一句古老格言的精神：亲近你的朋友，更要亲近你的敌人。在荒野之中，这个氏族则是另一回事。]=],
		},
		{
			title = "在荒野之中",
			text = [=[• {b}{link:thousand-needles}千针石林{/link}。{/b} 恐怖图腾占据着{link:darkcloud-pinnacle}黑云峰{/link}，他们在那里的一团圣火旁埋葬死者。{link:freewind-post}乱风岗{/link}的{link:tauren}牛头人{/link}密切监视着他们。有人看到来历不明的密探拜访他们，而氏族的一个被逐者{link:arnak-grimtotem}阿纳克{/link}因谋杀和绑架而遭到通缉。
• {b}{link:stonetalon-mountains}石爪山脉{/link}。{/b} 恐怖图腾的袭击者突袭了山脉附近的一个牛头人村庄，几乎杀光了村里所有人。
• {b}{link:earthen-ring}大地之环{/link}。{/b} 并非每个恐怖图腾都走氏族的道路。这些日子里，一位名叫约恩·恐怖图腾的萨满祭司在{link:mulgore}莫高雷{/link}为大地之环效力。]=],
		},
	},
})
